inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "qwen-image/inpaint",
  "label": {
    "en": "Inpaint",
    "ru": "Inpaint"
  },
  "family": "qwen-image",
  "family_label": "Qwen Image",
  "tier": 0,
  "mode": "inpaint",
  "order": 30,
  "controls": [
    {
      "param": "prompt",
      "kind": "prompt",
      "superprompt": true
    },
    {
      "param": "seed",
      "kind": "seed"
    },
    {
      "param": "denoise",
      "kind": "slider",
      "min": 0.1,
      "max": 1.0,
      "step": 0.05,
      "label": {
        "en": "Repaint strength",
        "ru": "Сила перерисовки"
      },
      "default": 1.0,
      "tooltip": {
        "en": "How much of the masked area is redrawn. 0.1-0.25 refines what is already there; 0.3-0.5 reworks it noticeably; 0.6-1.0 replaces the content.",
        "ru": "Насколько сильно перерисовывается область. 0.1–0.25 — уточнение того, что есть; 0.3–0.5 — заметная переработка; 0.6–1.0 — замена содержимого."
      }
    },
    {
      "param": "megapixels",
      "kind": "slider",
      "min": 0.5,
      "max": 4.0,
      "step": 0.1,
      "default": 0.8,
      "label": {
        "en": "Processing resolution",
        "ru": "Разрешение обработки"
      },
      "tooltip": {
        "en": "Megapixels the masked crop is redrawn at. A small selection is upscaled toward this budget (more detail, slower); an oversized one is scaled down to it.",
        "ru": "В скольких мегапикселях перерисовывается вырезанный по маске фрагмент. Маленькое выделение увеличивается до этого бюджета (больше деталей, дольше), слишком большое — уменьшается."
      }
    },
    {
      "param": "context_pct",
      "kind": "slider",
      "min": 0.0,
      "max": 50.0,
      "step": 1.0,
      "default": 25.0,
      "label": {
        "en": "Context around the mask",
        "ru": "Контекст вокруг маски"
      },
      "tooltip": {
        "en": "How much of the surroundings goes into the crop, as a percent of the mask. More context helps the model match what is around; it also enlarges the crop, so less of the budget lands on the mask.",
        "ru": "Сколько окружения попадает в вырез, в процентах от маски. Больше контекста — модель лучше попадает в окружение, но вырез растёт, и на саму маску приходится меньше бюджета."
      }
    },
    {
      "param": "loras",
      "kind": "loras",
      "max": 8,
      "strength": [
        -2.0,
        2.0
      ]
    },
    {
      "param": "think_steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 12,
      "label": {
        "en": "Think steps (quality)",
        "ru": "Шаги размышления (качество)"
      },
      "default": 2,
      "tooltip": {
        "en": "How many times the sampler re-checks the repaint against its surroundings on every step. Each turn is another pass through the model, so this is the main quality-versus-time knob: 2 is enough for an ordinary repaint, 5+ for a hard one.",
        "ru": "Сколько раз на каждом шаге сэмплер сверяет перерисовку с окружением. Каждый заход — это ещё один проход через модель, поэтому здесь и решается «качество против времени»: 2 хватает обычной правке, 5 и больше — сложной."
      }
    },
    {
      "param": "steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 60,
      "label": {
        "en": "Steps",
        "ru": "Шаги"
      },
      "default": 4
    },
    {
      "param": "cfg",
      "kind": "number",
      "advanced": true,
      "min": 1.0,
      "max": 15,
      "step": 0.1,
      "label": {
        "en": "CFG",
        "ru": "CFG"
      },
      "default": 1.0
    }
  ],
  "refs": {
    "max": 0
  },
  "requires": [
    "source_image",
    "mask"
  ],
  "negative_prompt": false,
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "qwen_image_(2512|\\d+)_|Artius_Qwen_v"
    },
    {
      "title": "studio:clip",
      "input": "clip_name",
      "folder": "text_encoders",
      "match": "qwen_2\\.5_vl_7b"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "qwen_image_vae"
    },
    {
      "title": "studio:lora_lightning",
      "match": "Qwen-Image-2512-Lightning-4steps.*bf16",
      "folder": "loras"
    }
  ],
  "dependencies": [
    {
      "pack": "LanPaint",
      "nodes": [
        "LanPaint_KSampler",
        "LanPaint_MaskBlend"
      ]
    }
  ]
}
